using System.Net; using System.Net.Http.Json; using Microsoft.AspNetCore.Mvc.Testing; using Microsoft.Extensions.Configuration; using Xunit;
public sealed class AuthOwnershipTests : IAsyncLifetime
{
  private WebApplicationFactory<Program> _factory = null!; private HttpClient _a = null!; private HttpClient _b = null!; private const string AP="A-Only-Learning-Password-2026!"; private const string BP="B-Only-Learning-Password-2026!";
  public async ValueTask InitializeAsync(){ Environment.SetEnvironmentVariable("ROADMAP_AUTH_DB", $"RoadmapAuth11_{Guid.NewGuid():N}"); _factory=new WebApplicationFactory<Program>(); _a=_factory.CreateClient(new WebApplicationFactoryClientOptions{HandleCookies=true,AllowAutoRedirect=false}); _b=_factory.CreateClient(new WebApplicationFactoryClientOptions{HandleCookies=true,AllowAutoRedirect=false}); await Register(_a,"learner-a@example.test",AP); await Register(_b,"learner-b@example.test",BP); }
  static async Task Register(HttpClient c,string e,string p){var r=await c.PostAsJsonAsync("/api/register",new{email=e,password=p}); Assert.Equal(HttpStatusCode.OK,r.StatusCode);}
  static async Task<string> Csrf(HttpClient c){var r=await c.GetFromJsonAsync<Csrf>("/api/csrf"); return r!.Token;}
  [Fact] public async Task Anonymous_is_denied(){using var c=_factory.CreateClient(new WebApplicationFactoryClientOptions{AllowAutoRedirect=false}); Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/expenses/1")).StatusCode);}
  [Fact] public async Task Cookie_owner_filter_blocks_cross_owner_and_csrf_is_required(){var t=await Csrf(_a); var ok=await _a.PostAsJsonAsync("/api/expenses",new{amount=12.34,note="A",ownerUserId="attacker"}); Assert.Equal(HttpStatusCode.BadRequest,ok.StatusCode); var req=new HttpRequestMessage(HttpMethod.Post,"/api/expenses"){Content=JsonContent.Create(new{amount=12.34,note="A",ownerUserId="attacker"})}; req.Headers.Add("X-CSRF-TOKEN",t); var created=await _a.SendAsync(req); Assert.Equal(HttpStatusCode.Created,created.StatusCode); var id=(await created.Content.ReadFromJsonAsync<ExpenseResult>())!.Id; Assert.Equal(HttpStatusCode.NotFound,(await _b.GetAsync($"/api/expenses/{id}")).StatusCode); var own=await _a.GetAsync($"/api/expenses/{id}"); Assert.Equal(HttpStatusCode.OK,own.StatusCode);}
  [Fact] public async Task Invalid_login_does_not_authenticate(){using var c=_factory.CreateClient(new WebApplicationFactoryClientOptions{AllowAutoRedirect=false}); var r=await c.PostAsJsonAsync("/api/login",new{email="learner-a@example.test",password="wrong-password"}); Assert.Equal(HttpStatusCode.Unauthorized,r.StatusCode); Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/expenses/1")).StatusCode);}
  public ValueTask DisposeAsync(){_a.Dispose();_b.Dispose();_factory.Dispose(); return ValueTask.CompletedTask;}
  sealed record Csrf(string Header,string Token); sealed record ExpenseResult(int Id,decimal Amount,string Note);
}
